dtsPropsFor.MovementRow:
movement: {
  id: string;
  type: "DEPOSIT" | "TRANSFER_IN" | "TRANSFER_OUT" | "OWN_TRANSFER_IN" | "OWN_TRANSFER_OUT";
  /** Monto con signo y 2 decimales, como string: "-1500.00" (salida), "25000.00" (entrada). */
  amount: string;
  /** Saldo de la cuenta después del movimiento, "23500.00". */
  balanceAfter: string;
  concept: string;
  reference: string;
  /** null en los DEPOSIT de la Tesorería. */
  counterparty: { name: string; clabeLast4: string } | null;
  transferId: string;
  /** ISO 8601; se muestra en hora de Ciudad de México. */
  occurredAt: string;
};
/** Solo la hora a la vista y sin borde, para listas agrupadas por día (MovementList); por omisión, fecha completa y borde. */
timeOnly?: boolean;

dtsPropsFor.Receipt:
/** Transferencia tal como la devolvió la API. */
transfer: {
  id: string;
  status: "PENDING_OTP" | "COMPLETED" | "REJECTED" | "FAILED" | "EXPIRED" | "SCHEDULED" | "CANCELLED";
  kind: "OWN" | "THIRD_PARTY";
  fromAccountId: string;
  destination: {
    type: "OWN_ACCOUNT" | "BENEFICIARY";
    accountId: string | null;
    beneficiaryId: string | null;
    displayName: string;
    clabeLast4: string;
  };
  /** Monto en pesos como string con 2 decimales, "5000.00". */
  amount: string;
  concept: string;
  reference: string | null;
  requiresOtp: boolean;
  otp: {
    channel: "EMAIL";
    deliveryStatus: "SENT" | "FAILED";
    maskedDestination: string;
    expiresAt: string;
    attemptsRemaining: number;
    resendsRemaining: number;
  } | null;
  rejectionReason: "INSUFFICIENT_FUNDS" | "DAILY_LIMIT_EXCEEDED" | null;
  failureReason: "INSUFFICIENT_FUNDS" | "DAILY_LIMIT_EXCEEDED" | "OTP_ATTEMPTS_EXHAUSTED" | null;
  /** Instante de envío RFC 3339, "2026-10-20T20:30:00Z" (solo las programadas, WEB-34): el comprobante lo muestra como "Programada para" con fecha y hora de la Ciudad de México. */
  scheduledFor: string | null;
  cancelledAt: string | null;
  createdAt: string;
  completedAt: string | null;
};
/** Cuenta de origen, si se conoce, para mostrar su nombre y CLABE enmascarada. */
fromAccount?: { name: string; clabe: string };

dtsPropsFor.AccountCard:
/** Montos en pesos como string con 2 decimales; CLABE de 18 dígitos (se enmascara). */
account: { name: string; clabe: string; balance: string };
/** Borde de selección de 2 px en el verde de acción. */
selected?: boolean;
/** Hace del nombre un botón de selección con aria-pressed (el saldo queda fuera del botón). */
onSelect?: () => void;
/** Acciones de la tarjeta (por ejemplo, "Ver movimientos"). */
children?: React.ReactNode;

dtsPropsFor.DailyLimitMeter:
/** Montos en pesos como string con 2 decimales, "50000.00". */
dailyLimit: { limit: string; used: string; remaining: string; resetsAt: string; timeZone: "America/Mexico_City" };
/** Muestra "Límite diario" y el límite arriba de la barra; por omisión no (la pantalla de cuentas pone su propio título). */
showHeader?: boolean;

dtsPropsFor.MovementList:
movements: ReadonlyArray<{
  id: string;
  type: "DEPOSIT" | "TRANSFER_IN" | "TRANSFER_OUT" | "OWN_TRANSFER_IN" | "OWN_TRANSFER_OUT";
  /** Monto con signo y 2 decimales, como string: "-1500.00" (salida), "25000.00" (entrada). */
  amount: string;
  /** Saldo de la cuenta después del movimiento, "23500.00". */
  balanceAfter: string;
  concept: string;
  reference: string;
  /** null en los DEPOSIT de la Tesorería. */
  counterparty: { name: string; clabeLast4: string } | null;
  transferId: string;
  /** ISO 8601; se muestra en hora de Ciudad de México. */
  occurredAt: string;
}>;
/** Fecha de referencia para los encabezados "Hoy" y "Ayer" (por omisión, la actual). */
now?: Date;

dtsPropsFor.ScheduleField:
/** Opción elegida: con "Programar" aparece la fecha de envío. */
when: "NOW" | "SCHEDULED";
/** Lo que devuelve `register('when')` de react-hook-form para el grupo de radios. */
whenField: { name: string; onChange: (event: unknown) => Promise<unknown>; onBlur: (event: unknown) => Promise<unknown>; ref: (element: HTMLInputElement | null) => void };
/** Lo que devuelve `register('scheduledFor')` para la fecha (AAAA-MM-DD). */
dateField: { name: string; onChange: (event: unknown) => Promise<unknown>; onBlur: (event: unknown) => Promise<unknown>; ref: (element: HTMLInputElement | null) => void };
/** Lo que devuelve `register('scheduledTime')` para la hora (HH:MM, hora de la Ciudad de México). Con ella, "Programar" muestra fecha y hora lado a lado (WEB-33). */
timeField?: { name: string; onChange: (event: unknown) => Promise<unknown>; onBlur: (event: unknown) => Promise<unknown>; ref: (element: HTMLInputElement | null) => void };
/** Error de la fecha, del formulario o de la API; se muestra junto al campo. */
error?: string;
/** Fecha de referencia del rango (lienzos con el reloj fijo); por omisión, la actual. */
now?: Date;

dtsPropsFor.StatementDownload:
/** Cuenta cuyo estado de cuenta se descarga (`accounts/<id>/statements/<AAAA-MM>` por el BFF). */
accountId: string;
/** `Account.createdAt`: el primer mes que se puede pedir (WEB-32). */
createdAt: string;
/** Fecha de referencia de los meses (lienzos con el reloj fijo); por omisión, la actual. */
now?: Date;
